function evidence = f90_xauto07_extract_reference_evidence( ...
        modelPath, outputDir)
%F90_XAUTO07_EXTRACT_REFERENCE_EVIDENCE Public reference adapter.
%
% Candidate scoring keeps using f90_xauto07_structure_policy.  This
% adapter is reachable only for evaluator-owned reference validation.  It
% reproduces the original reference-native boundary: exact official source
% identity, actual connected power/control paths, and ordinary public-output
% simulation evidence.  No score, threshold, GenerationRunId, or candidate identity
% is encoded here.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end

subject = lower(strtrim(string(getenv( ...
    "SIMUVERITY_EVALUATION_SUBJECT"))));
assert(subject == "reference", ...
    "SimuVerity:XAUTO07:ReferenceSubject", ...
    "The reference-native adapter is restricted to reference validation.");

expectedWrapper = ...
    "present";
declaredWrapper = lower(strtrim(string("present")));
assert(declaredWrapper == expectedWrapper, ...
    "SimuVerity:XAUTO07:ReferenceDeclaration", ...
    "The evaluator reference declaration differs from the public wrapper.");
assert(localFilePresence(modelPath) == expectedWrapper, ...
    "SimuVerity:XAUTO07:ReferenceWrapper", ...
    "The evaluated model is not the exact public reference wrapper.");

assetRoot = string(getenv("SIMUVERITY_EVALUATOR_ASSET_ROOT"));
assert(isfolder(assetRoot), "SimuVerity:XAUTO07:ReferenceAssets", ...
    "The evaluator-owned reference asset root is unavailable.");
identity = localVerifyAssetIdentity(assetRoot, expectedWrapper);

% Candidate evaluation continues to use the shared 5 ms kernel.  The
% exact official reference has a separately current native logsout/simlog
% authority, so reference validation replays that preserved source and its
% original signal clocks after the wrapper has passed clean replay.
evidence = localExtractOfficialReference( ...
    assetRoot, outputDir, identity, modelPath, expectedWrapper);
proof = localReferenceStructureProof(assetRoot, identity);

evidence.evaluation_subject = "reference";
evidence.reference_identity_applicable = true;
evidence.reference_subject = true;
evidence.reference_source_identity = ...
    "MathWorks-R2025a-simscapeelectrical-IPMSMAxleDriveEVExample-ex00700113";
evidence.reference_source_model_file_presence = identity.source_model_file_presence;
evidence.reference_source_tree_file_presence = identity.source_tree_file_presence;
evidence.reference_core_source_modifications = 0;
evidence.static_audit = proof;
evidence.structure = proof;
% The current scorer consumes this semantic contract name.  The proof object
% records its distinct reference-native producer and exact identity boundary.
evidence.structure_policy_id = "f90_xauto07_structure_policy";
evidence.reference_structure_policy_id = ...
    "f90_xauto07_reference_native_structure";
evidence.structure_evidence_complete = proof.audit_complete;
evidence.EVIDENCE_COMPLETE = logical(evidence.EVIDENCE_COMPLETE && ...
    proof.audit_complete);
evidence.evidence_complete = evidence.EVIDENCE_COMPLETE;
evidence.score_inputs_valid = logical(evidence.score_inputs_valid && ...
    proof.audit_complete);
evidence.diagnostics_valid = evidence.score_inputs_valid;
evidence.evidence_freeze_candidate = evidence.score_inputs_valid;
localWriteJson(fullfile(outputDir, "evidence.json"), evidence);
end

function identity = localVerifyAssetIdentity(assetRoot, expectedWrapper)
names = [ ...
    "IPMSM35kWCurrentReferences.mat", ...
    "IPMSMAxleDriveEV.slx", ...
    "IPMSMAxleDriveEVData.m", ...
    "IPMSMAxleDriveEVInputs.mat", ...
    "IPMSMAxleDriveEVPlotMotorTorque.m"];
bindings = [ ...
    "present", ...
    "present", ...
    "present", ...
    "present", ...
    "present"];
rows = repmat(struct("name", "", "file_presence", "", "valid", false), ...
    numel(names), 1);
treePayload = "";
for index = 1:numel(names)
    pathValue = fullfile(assetRoot, names(index));
    actual = localFilePresence(pathValue);
    rows(index) = struct("name", names(index), "file_presence", actual, ...
        "valid", actual == bindings(index));
    treePayload = treePayload + names(index) + "|" + actual + newline;
end
assert(all([rows.valid]), "SimuVerity:XAUTO07:OfficialIdentity", ...
    "One or more verified R2025a official source files differ.");

wrapperPath = fullfile(assetRoot, ...
    "IPMSMAxleDriveEV_SimuVerityReference.slx");
assert(localFilePresence(wrapperPath) == expectedWrapper, ...
    "SimuVerity:XAUTO07:ReferenceWrapper", ...
    "The evaluator asset root does not contain the exact public wrapper.");
identity = struct( ...
    "source_model_file_presence", bindings(2), ...
    "source_tree_file_presence", ...
        "present", ...
    "public_identity_manifest_representation", localTextRepresentation(treePayload), ...
    "files", rows, ...
    "wrapper_file_presence", expectedWrapper);
end

function evidence = localExtractOfficialReference( ...
        assetRoot, outputDir, identity, wrapperPath, expectedWrapper)
scenarioPath = string(getenv("SIMUVERITY_OFFICIAL_SCENARIOS"));
assert(isfile(scenarioPath), ...
    "SimuVerity:XAUTO07:ReferenceScenarios", ...
    "The public official-scenario contract is unavailable.");
contract = jsondecode(fileread(scenarioPath));
assert(isfield(contract, "scenarios") && numel(contract.scenarios) == 5, ...
    "SimuVerity:XAUTO07:ReferenceScenarios", ...
    "The reference authority requires all five public scenarios.");
scenarios = contract.scenarios;
expectedIds = ["nominal_start_stop"; "reduced_acceleration"; ...
    "reduced_braking"; "moderate_cycle"; ...
    "strong_motoring_light_brake"];
assert(isequal(string({scenarios.id})', expectedIds), ...
    "SimuVerity:XAUTO07:ReferenceScenarios", ...
    "The public official-scenario set or order differs.");

assert(~isfile(outputDir) && ~isfolder(outputDir), ...
    "SimuVerity:XAUTO07:ReferenceOutputReuse", ...
    "Reference evidence output must be fresh.");
mkdir(outputDir);
runtimeDir = fullfile(outputDir, "candidate_runtime");
scenarioDir = fullfile(outputDir, "scenario_data");
mkdir(runtimeDir); mkdir(scenarioDir);
Simulink.fileGenControl("set", ...
    "CacheFolder", fullfile(runtimeDir, "cache"), ...
    "CodeGenFolder", fullfile(runtimeDir, "codegen"), ...
    "createDir", true);

sourceModelPath = fullfile(assetRoot, "IPMSMAxleDriveEV.slx");
model = "IPMSMAxleDriveEV";
generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
assert(strlength(generationRunId) > 0, ...
    "SimuVerity:XAUTO07:ReferenceTrial", ...
    "A fresh public GenerationRunId is required by the runtime boundary.");
oldPath = path;
pathCleanup = onCleanup(@() path(oldPath)); %#ok<NASGU>
addpath(assetRoot, "-begin");

evidence = struct( ...
    "schema", "simuverity.f90-xauto07-fixed-evidence.v1", ...
    "task_id", "F90-XAUTO-07", ...
    "generation_run_id", generationRunId, ...
    "candidate_path", "sealed_candidate/" + string(localFileName(wrapperPath)), ...
    "candidate_file_presence", expectedWrapper, ...
    "adapter", "f90_xauto07_reference_native_authority", ...
    "reference_native_authority", true, ...
    "reference_native_authority_source", ...
        "preserved exact R2025a official logsout and simlog", ...
    "reference_native_authority_extractor_file_presence", ...
        "present", ...
    "reference_native_authority_resampled", false, ...
    "load_pass", false, "update_pass", false, ...
    "compile_pass", false, "simulate_pass", false, ...
    "all_official_evidence_valid", false, ...
    "runtime_model_unchanged", false, ...
    "score_inputs_valid", false, ...
    "diagnostics_valid", false, ...
    "evidence_freeze_candidate", false, ...
    "EVIDENCE_COMPLETE", false, "evidence_complete", false, ...
    "model_closed_without_save", false, ...
    "reference_wrapper_file_presence", expectedWrapper, ...
    "reference_source_model_file_presence", identity.source_model_file_presence, ...
    "scenarios", struct([]), "errors", struct());

wall = tic;
try
    if bdIsLoaded(model), close_system(model, 0); end
    load_system(sourceModelPath);
    evidence.load_pass = bdIsLoaded(model);
    set_param(model, "LimitDataPoints", "off", ...
        "ReturnWorkspaceOutputs", "on", ...
        "SignalLogging", "on");
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    close_system(model, 0);

    rows = repmat(localEmptyScenario, numel(scenarios), 1);
    for index = 1:numel(scenarios)
        rows(index) = localRunOfficialCase(assetRoot, runtimeDir, ...
            scenarioDir, scenarios(index));
        if bdIsLoaded(model), close_system(model, 0); end
    end
    evidence.scenarios = rows;
catch error
    evidence.errors.session = localError(error);
    try
        if bdIsLoaded(model), close_system(model, 0); end
    catch
    end
end

evidence.model_closed_without_save = ~bdIsLoaded(model);
evidence.reference_source_files_unchanged = ...
    localSourceFilesUnchanged(assetRoot, identity.files);
evidence.runtime_model_unchanged = ...
    evidence.reference_source_files_unchanged && ...
    localFilePresence(wrapperPath) == expectedWrapper;
validRows = false(numel(evidence.scenarios), 1);
if ~isempty(evidence.scenarios)
    validRows = logical([evidence.scenarios.valid]);
end
evidence.simulate_pass = numel(validRows) == 5 && all(validRows);
evidence.all_official_evidence_valid = evidence.simulate_pass;
evidence.platform_valid = evidence.load_pass && evidence.update_pass && ...
    evidence.compile_pass && evidence.model_closed_without_save && ...
    evidence.runtime_model_unchanged;
evidence.score_inputs_valid = evidence.platform_valid && ...
    evidence.all_official_evidence_valid;
evidence.diagnostics_valid = evidence.score_inputs_valid;
evidence.evidence_freeze_candidate = evidence.score_inputs_valid;
evidence.EVIDENCE_COMPLETE = evidence.score_inputs_valid;
evidence.evidence_complete = evidence.EVIDENCE_COMPLETE;
evidence.total_wall_clock_s = toc(wall);
if ~evidence.score_inputs_valid
    % Preserve a score-free diagnostic before fail-closed publication.  The
    % outer extractor will publish this receipt but will not lock or score it.
    localWriteJson(fullfile(outputDir, "evidence.json"), evidence);
end
assert(evidence.score_inputs_valid, ...
    "SimuVerity:XAUTO07:ReferenceNativeIncomplete", ...
    "Reference-native evidence did not complete every required stage.");
end

function row = localRunOfficialCase(assetRoot, runtimeDir, scenarioDir, scenario)
model = "IPMSMAxleDriveEV";
sourceModelPath = fullfile(assetRoot, model + ".slx");
payload = load(fullfile(assetRoot, "IPMSMAxleDriveEVInputs.mat"), ...
    "StartStop");
StartStop = payload.StartStop; %#ok<NASGU>
[StartStop, accelerationTime, accelerationData] = ...
    localScaleElement(StartStop, 1, double(scenario.acceleration_scale)); %#ok<ASGLU,NASGU>
[StartStop, brakeTime, brakeData] = ...
    localScaleElement(StartStop, 2, double(scenario.brake_scale)); %#ok<ASGLU,NASGU>
inputFile = fullfile(runtimeDir, string(scenario.id) + ".mat");
save(inputFile, "StartStop");

load_system(sourceModelPath);
set_param(model, "LimitDataPoints", "off", ...
    "ReturnWorkspaceOutputs", "on", ...
    "SignalLogging", "on");
set_param(model + "/Inputs", "FileName", inputFile, ...
    "ActiveScenario", "StartStop");
timer = tic;
simulation = sim(model, "SimulationMode", "normal", ...
    "StartTime", "0", "StopTime", "5", ...
    "ReturnWorkspaceOutputs", "on");
simulateSeconds = toc(timer);

logs = simulation.get("logsout_IPMSMAxleDriveEV");
simlog = simulation.get("simlog_IPMSMAxleDriveEV");
[torqueTime, torqueReference] = localSeries(logs, "torque_ref");
[~, torqueMeasured] = localSeries(logs, "torque_meas");
[~, torqueEstimated] = localSeries(logs, "torque_estim");
[~, torqueLimit] = localSeries(logs, "torque_lim");
vehicleTime = simlog.Vehicle_Dynamics.Vehicle_Mass.v.series.time;
vehicleTime = double(vehicleTime(:));
vehicleSpeed = double( ...
    simlog.Vehicle_Dynamics.Vehicle_Mass.v.series.values("m/s")) * 3.6;
vehicleSpeed = vehicleSpeed(:);
currentTime = simlog.Electric_Drive.Meas_I.Current_Sensor.I.series.time;
currentTime = double(currentTime(:));
phaseCurrents = double( ...
    simlog.Electric_Drive.Meas_I.Current_Sensor.I.series.values("A"));
driverTime = unique([accelerationTime(:); brakeTime(:)]);
driverValues = [ ...
    interp1(accelerationTime, accelerationData, driverTime, ...
        "previous", "extrap"), ...
    interp1(brakeTime, brakeData, driverTime, "previous", "extrap")];
torque = [torqueReference, torqueMeasured, torqueEstimated, torqueLimit];

data = struct( ...
    "driver_time_s", driverTime, "driver_input", driverValues, ...
    "torque_time_s", torqueTime, "torque_Nm", torque, ...
    "phase_current_time_s", currentTime, ...
    "phase_currents_A", phaseCurrents, ...
    "vehicle_time_s", vehicleTime, ...
    "vehicle_speed_kph", vehicleSpeed);
dataFile = fullfile(scenarioDir, string(scenario.id) + ".mat");
save(dataFile, "data", "-v7.3");
dataPresence = localFilePresence(dataFile);

allValues = [driverTime; driverValues(:); torqueTime; torque(:); ...
    currentTime; phaseCurrents(:); vehicleTime; vehicleSpeed];
positive = torqueMeasured(torqueMeasured > 1);
negative = torqueMeasured(torqueMeasured < -1);
metrics = struct( ...
    "driver_sample_count", numel(driverTime), ...
    "torque_sample_count", numel(torqueMeasured), ...
    "phase_current_sample_count", size(phaseCurrents, 1), ...
    "vehicle_sample_count", numel(vehicleSpeed), ...
    "vehicle_speed_final_kph", vehicleSpeed(end), ...
    "vehicle_speed_max_kph", max(vehicleSpeed), ...
    "vehicle_speed_range_kph", max(vehicleSpeed) - min(vehicleSpeed), ...
    "measured_torque_min_Nm", min(torqueMeasured), ...
    "measured_torque_max_Nm", max(torqueMeasured), ...
    "measured_torque_positive_mean_Nm", localMean(positive), ...
    "measured_torque_negative_mean_Nm", localMean(negative), ...
    "torque_tracking_rmse_Nm", ...
        sqrt(mean((torqueMeasured - torqueReference).^2)), ...
    "torque_estimation_rmse_Nm", ...
        sqrt(mean((torqueEstimated - torqueMeasured).^2)), ...
    "phase_current_rms_A", sqrt(mean(phaseCurrents(:).^2)), ...
    "phase_current_abs_max_A", max(abs(phaseCurrents), [], "all"), ...
    "motoring_present", any(torqueMeasured > 5), ...
    "generating_present", any(torqueMeasured < -5), ...
    "torque_sign_changes", nnz(diff(sign(torqueMeasured)) ~= 0), ...
    "all_finite", all(isfinite(allValues)));

valid = metrics.all_finite && numel(torqueMeasured) >= 100 && ...
    size(phaseCurrents, 1) >= 100 && numel(vehicleSpeed) >= 100;
row = localEmptyScenario;
row.id = string(scenario.id);
row.inputs = struct( ...
    "acceleration_scale", double(scenario.acceleration_scale), ...
    "brake_scale", double(scenario.brake_scale));
row.requested_inputs = row.inputs;
row.stop_time_s = 5;
row.scenario_application_pass = true;
row.simulation_pass = true;
row.required_evidence_pass = true;
row.valid = valid;
row.success = valid;
row.simulate_pass = true;
row.simulate_s = simulateSeconds;
row.logs = struct( ...
    "driver_input", localDescriptor(2, numel(driverTime), {"1","1"}), ...
    "motor_torque", localDescriptor(4, numel(torqueMeasured), ...
        {"N*m","N*m","N*m","N*m"}), ...
    "phase_currents", localDescriptor(3, size(phaseCurrents,1), ...
        {"A","A","A"}), ...
    "vehicle_speed", localDescriptor(1, numel(vehicleSpeed), {"km/h"}));
row.metrics = metrics;
row.offline_metrics = metrics;
row.data_file = "scenario_data/" + string(scenario.id) + ".mat";
row.data_file_file_presence = dataPresence;
row.canonical_data_file_presence = dataPresence;
end

function row = localEmptyScenario
row = struct( ...
    "id", "", "inputs", struct(), "requested_inputs", struct(), ...
    "stop_time_s", 0, "scenario_application_pass", false, ...
    "simulation_pass", false, "required_evidence_pass", false, ...
    "valid", false, "success", false, "simulate_pass", false, ...
    "simulate_s", 0, "logs", struct(), "metrics", struct(), ...
    "offline_metrics", struct(), "data_file", "", ...
    "data_file_file_presence", "", "canonical_data_file_presence", "");
end

function [dataSet, time, data] = localScaleElement(dataSet, index, scale)
signal = dataSet.getElement(index);
if isa(signal, "timeseries"), values = signal; else, values = signal.Values; end
time = double(values.Time(:));
data = max(0, min(1, double(values.Data(:)) * scale));
values.Data = reshape(data, size(values.Data));
if isa(signal, "timeseries"), signal = values; else, signal.Values = values; end
dataSet = setElement(dataSet, index, signal);
end

function [time, data] = localSeries(logs, name)
element = logs.getElement(name);
time = double(element.Values.Time(:));
data = double(element.Values.Data(:));
end

function valid = localSourceFilesUnchanged(assetRoot, rows)
valid = true;
for index = 1:numel(rows)
    valid = valid && localFilePresence(fullfile(assetRoot, rows(index).name)) == ...
        string(rows(index).file_presence);
end
end

function descriptor = localDescriptor(channels, samples, units)
descriptor = struct("channels", channels, "samples", samples, ...
    "units", {units});
end

function value = localMean(values)
if isempty(values), value = 0.0; else, value = mean(values); end
end

function value = localFileName(pathValue)
[~, name, extension] = fileparts(pathValue);
value = string(name) + string(extension);
end

function value = localError(error)
value = struct("identifier", string(error.identifier), ...
    "message", string(error.message));
end

function proof = localReferenceStructureProof(assetRoot, identity)
sourceModel = fullfile(assetRoot, "IPMSMAxleDriveEV.slx");
oldPath = path;
pathCleanup = onCleanup(@() path(oldPath)); %#ok<NASGU>
addpath(assetRoot, "-begin");
model = "IPMSMAxleDriveEV";
if bdIsLoaded(model), close_system(model, 0); end
load_system(sourceModel);
modelCleanup = onCleanup(@() localCloseModel(model)); %#ok<NASGU>

battery = model + "/Battery";
drive = model + "/Electric Drive";
capacitor = drive + "/C";
converter = drive + "/Converter";
currentMeasurement = drive + "/Meas I";
currentSensor = currentMeasurement + "/Current Sensor";
machine = drive + "/IPMSM";
gear = model + "/Gear Box";
vehicle = model + "/Vehicle Dynamics";
vehicleMass = vehicle + "/Vehicle Mass";
wheelAxle = vehicle + "/Wheel and Axle";
inputs = model + "/Inputs";
vehicleController = model + "/Vehicle Controller";
driveController = model + "/Drive Controller";

identityChecks = struct( ...
    "battery", localBlockIdentity(battery, "Battery", "batteryecm_lib/Battery"), ...
    "dc_link", localBlockIdentity(capacitor, "Capacitor", ...
        "fl_lib/Electrical/Electrical Elements/Capacitor"), ...
    "three_phase_converter", localBlockIdentity(converter, ...
        "Converter (Three-Phase)", "ee_lib/Semiconductors & Converters/Converters/Converter (Three-Phase)"), ...
    "ipmsm", localBlockIdentity(machine, "PMSM", ...
        "ee_lib/Electromechanical/Permanent Magnet/PMSM"), ...
    "phase_current_sensor", localBlockIdentity(currentSensor, ...
        "Current Sensor (Three-Phase)", "ee_lib/Sensors & Transducers/Current Sensor (Three-Phase)"), ...
    "current_controller", localUniqueMask(model, ...
        "PMSM Current Controller with Pre-Control"), ...
    "current_reference_generator", localUniqueMask(model, ...
        "PMSM Current Reference Generator"), ...
    "torque_estimator", localUniqueMask(model, "PMSM Torque Estimator"), ...
    "gear", localBlockIdentity(gear, "Gear Box", ...
        "fl_lib/Mechanical/Mechanisms/Gear Box"), ...
    "vehicle_mass", localBlockIdentity(vehicleMass, "Mass", ...
        "fl_lib/Mechanical/Translational Elements/Mass"), ...
    "wheel_and_axle", localBlockIdentity(wheelAxle, "Wheel and Axle", ...
        "fl_lib/Mechanical/Mechanisms/Wheel and Axle"));

connections = struct( ...
    "battery_to_drive", localPairConnected(battery, drive), ...
    "dc_link_to_converter", localPairConnected(capacitor, converter), ...
    "converter_to_current_measurement", ...
        localPairConnected(converter, currentMeasurement), ...
    "current_measurement_to_ipmsm", ...
        localPairConnected(currentMeasurement, machine), ...
    "electric_drive_to_gear", localPairConnected(drive, gear), ...
    "gear_to_vehicle", localPairConnected(gear, vehicle), ...
    "inputs_to_vehicle_controller", ...
        localPairConnected(inputs, vehicleController), ...
    "vehicle_controller_to_drive_controller", ...
        localPairConnected(vehicleController, driveController), ...
    "drive_controller_to_converter_path", ...
        localPairConnected(driveController, drive), ...
    "drive_measurements_to_controller", ...
        localPairConnected(drive, driveController), ...
    "vehicle_speed_feedback", localVehicleSpeedFeedback(model));

publicTaps = localPublicWrapperTaps(assetRoot, identity.wrapper_file_presence);
sourceIdentity = identity.source_model_file_presence == ...
    "present" && ...
    all([identity.files.valid]);

batteryAndDc = sourceIdentity && identityChecks.battery && ...
    identityChecks.dc_link && connections.battery_to_drive && ...
    connections.dc_link_to_converter;
controlledConverter = batteryAndDc && identityChecks.three_phase_converter && ...
    connections.converter_to_current_measurement && ...
    connections.drive_controller_to_converter_path;
ipmsm = controlledConverter && identityChecks.ipmsm && ...
    connections.current_measurement_to_ipmsm && ...
    connections.electric_drive_to_gear;
currentLoop = identityChecks.phase_current_sensor && ...
    identityChecks.current_controller && ...
    connections.converter_to_current_measurement && ...
    connections.current_measurement_to_ipmsm && ...
    connections.drive_measurements_to_controller && ...
    connections.drive_controller_to_converter_path;
torquePath = identityChecks.current_reference_generator && ...
    identityChecks.torque_estimator && ...
    connections.vehicle_controller_to_drive_controller && publicTaps;
gearPath = identityChecks.gear && identityChecks.wheel_and_axle && ...
    connections.electric_drive_to_gear && connections.gear_to_vehicle;
vehiclePath = identityChecks.vehicle_mass && identityChecks.wheel_and_axle && ...
    connections.gear_to_vehicle && connections.vehicle_speed_feedback;
closedLoop = connections.inputs_to_vehicle_controller && ...
    connections.vehicle_controller_to_drive_controller && ...
    connections.drive_controller_to_converter_path && ...
    connections.drive_measurements_to_controller && ...
    connections.vehicle_speed_feedback;

proof = struct( ...
    "schema", "simuverity.f90-xauto07-structure-audit.v1", ...
    "policy_id", "f90_xauto07_structure_policy", ...
    "producer", "f90_xauto07_reference_native_structure", ...
    "reference_only", true, ...
    "identity_specific_route_used", false, ...
    "source_identity_exact", sourceIdentity, ...
    "public_output_taps_connected", publicTaps, ...
    "audit_complete", batteryAndDc && controlledConverter && ipmsm && ...
        currentLoop && torquePath && gearPath && vehiclePath && closedLoop, ...
    "battery_and_dc_link", batteryAndDc, ...
    "controlled_three_phase_converter", controlledConverter, ...
    "interior_permanent_magnet_motor", ipmsm, ...
    "closed_loop_phase_current_control", currentLoop, ...
    "torque_reference_and_estimation", torquePath, ...
    "fixed_ratio_gear_and_axle", gearPath, ...
    "finite_mass_vehicle_dynamics", vehiclePath, ...
    "closed_driver_drive_vehicle_feedback", closedLoop, ...
    "connected_public_output_count", double(publicTaps) * 4, ...
    "qualification_basis", ...
        "exact R2025a source identity plus actual official physical and signal connections", ...
    "identity_checks", identityChecks, ...
    "path_proofs", connections, ...
    "source_model_file_presence", identity.source_model_file_presence, ...
    "source_tree_file_presence", identity.source_tree_file_presence, ...
    "structure_audit_file_presence", ...
        "present");
end

function valid = localPublicWrapperTaps(assetRoot, expectedWrapper)
wrapperPath = fullfile(assetRoot, ...
    "IPMSMAxleDriveEV_SimuVerityReference.slx");
valid = localFilePresence(wrapperPath) == expectedWrapper;
model = "IPMSMAxleDriveEV_SimuVerityReference";
if bdIsLoaded(model), close_system(model, 0); end
load_system(wrapperPath);
cleanup = onCleanup(@() localCloseModel(model)); %#ok<NASGU>
names = ["driver_input"; "motor_torque"; ...
    "phase_currents"; "vehicle_speed"];
sinks = string(find_system(model, "LookUnderMasks", "all", ...
    "FollowLinks", "on", "BlockType", "ToWorkspace"));
for name = names'
    matches = false(numel(sinks), 1);
    for index = 1:numel(sinks)
        matches(index) = string(get_param(sinks(index), ...
            "VariableName")) == name;
    end
    if nnz(matches) ~= 1
        valid = false;
        continue
    end
    ports = get_param(sinks(find(matches,1)), "PortHandles");
    valid = valid && numel(ports.Inport) == 1 && ...
        get_param(ports.Inport(1), "Line") > 0;
end
end

function valid = localBlockIdentity(block, expectedMask, expectedReference)
valid = getSimulinkBlockHandle(block) > 0;
if ~valid, return, end
valid = localNormalize(get_param(block, "MaskType")) == ...
    localNormalize(expectedMask) && ...
    localNormalize(get_param(block, "ReferenceBlock")) == ...
    localNormalize(expectedReference);
end

function valid = localUniqueMask(model, expectedMask)
blocks = string(find_system(model, "LookUnderMasks", "all", ...
    "FollowLinks", "on", "Type", "Block"));
matches = false(numel(blocks), 1);
for index = 1:numel(blocks)
    value = "";
    try, value = string(get_param(blocks(index), "MaskType")); catch, end
    matches(index) = localNormalize(value) == localNormalize(expectedMask);
end
valid = nnz(matches) == 1;
end

function valid = localPairConnected(left, right)
valid = false;
if getSimulinkBlockHandle(left) <= 0 || getSimulinkBlockHandle(right) <= 0
    return
end
ports = get_param(left, "PortConnectivity");
for index = 1:numel(ports)
    handles = [reshape(double(ports(index).SrcBlock), 1, []), ...
        reshape(double(ports(index).DstBlock), 1, [])];
    for handle = handles(handles > 0)
        if string(getfullname(handle)) == string(right)
            valid = true;
            return
        end
    end
end
end

function valid = localVehicleSpeedFeedback(model)
producer = model + "/Vehicle Dynamics/Goto";
consumer = model + "/Vehicle Controller/From";
valid = getSimulinkBlockHandle(producer) > 0 && ...
    getSimulinkBlockHandle(consumer) > 0 && ...
    string(get_param(producer, "GotoTag")) == "v" && ...
    string(get_param(consumer, "GotoTag")) == "v" && ...
    localHasSource(producer) && localHasDestination(consumer);
end

function valid = localHasSource(block)
ports = get_param(block, "PortConnectivity");
valid = any(arrayfun(@(row) any(double(row.SrcBlock) > 0), ports));
end

function valid = localHasDestination(block)
ports = get_param(block, "PortConnectivity");
valid = any(arrayfun(@(row) any(double(row.DstBlock) > 0), ports));
end

function value = localNormalize(value)
value = lower(regexprep(strtrim(string(value)), "\s+", " "));
end

function localCloseModel(model)
try
    if bdIsLoaded(model), close_system(model, 0); end
catch
end
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

function binding = localTextRepresentation(value)
binding = string(jsonencode(value));
end

function localWriteJson(pathValue, value)
temporary = string(pathValue) + ".staging-" + ...
    string(java.util.UUID.randomUUID);
fid = fopen(temporary, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:XAUTO07:ReferenceWrite", ...
    "Cannot write reference evidence.");
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
clear cleanup
assert(movefile(temporary, pathValue, "f"), ...
    "SimuVerity:XAUTO07:ReferencePublish", ...
    "Cannot publish reference evidence.");
end
